INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(4401, 'Numbers 33:13', 'Numbers', 33, 13, '&nbsp;د دفقه نه الوش ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4402, 'Numbers 33:14', 'Numbers', 33, 14, '&nbsp;هغوئ د الوش نه خېمې اوچتې کړې او په رفيديم کښې يې ولګولې، چرته چې د خلقو دپاره د څښلو اوبۀ نۀ وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4403, 'Numbers 33:40', 'Numbers', 33, 40, '&nbsp;په جنوبى کنعان کښې د عراد بادشاه خبر شو چې اِسرائيليان راروان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4404, 'Numbers 33:50', 'Numbers', 33, 50, '&nbsp;د اُردن نه پورې يريحو ته مخامخ د موآب په مېدانونو کښې مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4405, 'Numbers 33:51', 'Numbers', 33, 51, '&nbsp;”بنى اِسرائيلو ته ووايه، کله چې تاسو د اُردن نه د کنعان مُلک ته واوړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4406, 'Numbers 33:52', 'Numbers', 33, 52, '&nbsp;تاسو د هغه مُلک ټول اوسېدونکى وشړئ. د هغوئ ټولې مجسمې او بُتان مات کړئ او د هغوئ ټولې علاقائى عبادتخانې ورانې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4407, 'Numbers 33:53', 'Numbers', 33, 53, '&nbsp;هغه مُلک قبضه کړئ او په هغې کښې اوسېږئ، ځکه چې زۀ هغه تاسو له درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4408, 'Numbers 33:54', 'Numbers', 33, 54, '&nbsp;هغه زمکه د پچې په ذريعه په بېلو بېلو قبيلو او قومونو باندې تقسيم کړئ. لوئ قبيلې له ډېره زمکه ورکړئ او وړې قبيلې له لږه زمکه ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4409, 'Numbers 33:55', 'Numbers', 33, 55, '&nbsp;خو کۀ تاسو د هغه مُلک اوسېدونکى ونۀ شړل، نو هغوئ به ستاسو دپاره داسې وى لکه چې په سترګو کښې تېرۀ خسڼے او د لارې خنډ وى، چرته چې تاسو اوسېږئ نو هلته به هغوئ تاسو له تکليف درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4410, 'Numbers 33:56', 'Numbers', 33, 56, '&nbsp;کۀ تاسو هغوئ ونۀ شړل، نو زۀ به تاسو تباه کړم، لکه څنګه چې ما د هغوئ د تباه کولو منصوبه جوړه کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4411, 'Numbers 34:1', 'Numbers', 34, 1, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4412, 'Numbers 34:2', 'Numbers', 34, 2, '&nbsp;او د بنى اِسرائيلو دپاره يې دا اصُول ورته وښودل، ”کله چې تاسو کنعان ته ورننوځئ، کوم مُلک چې زۀ تاسو له درکوم، ستاسو د علاقې حدونه به داسې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4413, 'Numbers 34:3', 'Numbers', 34, 3, '&nbsp;جنوبى سرحد به د صين صحرا او د ادوم سرحد پورې وى. دا به د نمرخاتۀ په طرف د مالګې درياب د جنوبى آخرى سر نه شروع کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4414, 'Numbers 34:4', 'Numbers', 34, 4, '&nbsp;بيا به دا په جنوب کښې د لړم درې طرف ته تاو وى او د صين صحرا نه واخله تر قادِس برنيع پورې به وى. د هغه ځائ نه به دا سرحد حصر ادار او عصمون ته ورسيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4415, 'Numbers 34:5', 'Numbers', 34, 5, '&nbsp;چرته چې دا د مِصر په سرحد کښې او د مديترانى د سمندر په آخرى سر کښې د وادۍ طرف ته تاو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4416, 'Numbers 34:6', 'Numbers', 34, 6, '&nbsp;د مديترانى د سمندر به يې د نمرپرېواتۀ سرحد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4417, 'Numbers 34:7', 'Numbers', 34, 7, '&nbsp;شمالى سرحد به د مديترانى د سمندر نه شروع کيږى چې د هور غرۀ پورې به وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4418, 'Numbers 34:8', 'Numbers', 34, 8, '&nbsp;او د هغه ځائ نه د حمات درې پورې به وى او صداد ته به ورسيږى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4419, 'Numbers 34:9', 'Numbers', 34, 9, '&nbsp;او زفرون ته به هم ورسيږى او په حصر عينان کښې به ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4420, 'Numbers 34:10', 'Numbers', 34, 10, '&nbsp;د نمرخاتۀ سرحد به د حصر عينان نه شروع کيږى چې د شفام پورې به وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4421, 'Numbers 34:11', 'Numbers', 34, 11, '&nbsp;بيا به دا د عين نمرخاتۀ طرف رِبله ته ورسيږى او د ګليل درياب نمرخاتۀ غاړې غرونو ته به ورسيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4422, 'Numbers 34:12', 'Numbers', 34, 12, '&nbsp;بيا د اُردن سيند سره د مالګې درياب ته به ورسيږى. دا به ستاسو او د دې نه ګېرچاپېره سرحدونه وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4423, 'Numbers 34:13', 'Numbers', 34, 13, '&nbsp;نو موسىٰ بنى اِسرائيلو ته وفرمائيل، ”دا هغه مُلک دے چې د پچې اچولو سره به تاسو ته ملاويږى، هغه زمکه چې مالِک خُدائ نهۀ نيمو قبيلو ته په حواله کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4424, 'Numbers 34:14', 'Numbers', 34, 14, '&nbsp;د روبين او جاد او د منسى نيمې قبيلې ته مخکښې خپل ميراث مِلاو شوے دے، چې د هغوئ د کورَنو په مطابق تقسيم شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4425, 'Numbers 34:15', 'Numbers', 34, 15, '&nbsp;دې دوه نيمو قبيلو ته د اُردن سيند نمرخاتۀ طرف ته يريحو ته مخامخ خپله زمکه مِلاو شوې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4426, 'Numbers 34:16', 'Numbers', 34, 16, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4427, 'Numbers 34:17', 'Numbers', 34, 17, '&nbsp;”اِلى‌عزر اِمام او د نون زوئ يشوَع به په خلقو باندې زمکه تقسيم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4428, 'Numbers 34:18', 'Numbers', 34, 18, '&nbsp;د هرې قبيلې نه يو يو مشر سړے هم خوښ کړه چې د دې په تقسيمولو کښې د هغوئ مدد وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4429, 'Numbers 34:29', 'Numbers', 34, 29, '&nbsp;دا هغه کسان دى چې مالِک خُدائ د کنعان په مُلک کښې په خلقو باندې د زمکې تقسيمولو دپاره مقرر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4430, 'Numbers 35:1', 'Numbers', 35, 1, '&nbsp;د اُردن نه پورې يريحو ته مخامخ د موآب په مېدانونو کښې مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4431, 'Numbers 35:2', 'Numbers', 35, 2, '&nbsp;”بنى اِسرائيلو ته ووايه چې کوم ميراث هغوئ ته مِلاو شوے دے د هغې نه به څۀ ښارونه د اوسېدو دپاره او د ښارونو نه ګېرچاپېره د څرن زمکه خامخا ليويانو له ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4432, 'Numbers 35:3', 'Numbers', 35, 3, '&nbsp;دا ښارونه به د ليويانو وى او هلته به اوسيږى. د څرن زمکه به د هغوئ د څاروو او نورو ځناورو دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4433, 'Numbers 35:4', 'Numbers', 35, 4, '&nbsp;د څرن زمکه به د ښار دېوالونو نه بهر پينځۀ سوه ګزه په هر طرف خوره وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4434, 'Numbers 35:5', 'Numbers', 35, 5, '&nbsp;چې هغه علاقه څلور واړو طرفونو ته تقريباً زر ګزه وى او ښار يې په مينځ کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4435, 'Numbers 35:6', 'Numbers', 35, 6, '&nbsp;تاسو به ليويانو له د پناه دپاره شپږ ښارونه ورکوئ کۀ چرې يو سړے يو کس په غلطۍ سره ووژنى نو هلته به تښتى. د دې نه علاوه، هغوئ له دوه څلوېښت ښارونه ورکړئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4436, 'Numbers 35:7', 'Numbers', 35, 7, '&nbsp;د څرن د زمکې سره، د هغوئ به ټول اتۀ څلوېښت ښارونه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4437, 'Numbers 35:8', 'Numbers', 35, 8, '&nbsp;په هره قبيله کښې د ليويانو د ښارونو شمېر دې د هغې علاقې د غټوالى يا وړوکوالى په اندازه معلوم کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4438, 'Numbers 35:9', 'Numbers', 35, 9, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4439, 'Numbers 35:10', 'Numbers', 35, 10, '&nbsp;”بنى اِسرائيلو ته ووايه، کله چې تاسو د اُردن سيند نه پورې غاړه واوړئ او د کنعان مُلک ته ورننوځئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4440, 'Numbers 35:11', 'Numbers', 35, 11, '&nbsp;نو تاسو به د پناه ښارونه خوښ کړئ چې يو سړے په غلطۍ سره څوک مړ کړى نو چې هلته تښتېدلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4441, 'Numbers 35:12', 'Numbers', 35, 12, '&nbsp;هلته به د مړى د خپلوانو نه په حِفاظت کښې وى څوک چې بدل اخستل غواړى. چې په چا باندې د قتل اِلزام وى نو هغه به تر هغه پورې نۀ شى وژلے چې جرګې ته پېش شوے نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4442, 'Numbers 35:13', 'Numbers', 35, 13, '&nbsp;شپږ ښارونه خوښ کړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4443, 'Numbers 35:14', 'Numbers', 35, 14, '&nbsp;چې درې د اُردن دې غاړې ته وى او درې د کنعان په مُلک کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4444, 'Numbers 35:15', 'Numbers', 35, 15, '&nbsp;دا ځايونه به د بنى اِسرائيلو او د مسافرو دپاره د پناه ښارونه وى چې هغوئ د پردى مُلک وى يا په مستقله توګه اوسېدونکى وى. هر څوک چې په غلطۍ سره څوک ووژنى نو هغه به دې ښارونو ته تښتېدے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4445, 'Numbers 35:19', 'Numbers', 35, 19, '&nbsp;دا به د مړ شوى کس د نزدې خپلوانو ذمه وارى وى چې قاتِل مړ کړى. چې کله يې هم پېدا کړى، نو وبه يې وژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4446, 'Numbers 35:20', 'Numbers', 35, 20, '&nbsp;کۀ څوک د چا سره کينه لرى او د هغۀ د مرګ منصوبه جوړوى، په څۀ يې وولى او يا ديکه ورکړى نو دا يې قصداً وژنى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4447, 'Numbers 35:21', 'Numbers', 35, 21, '&nbsp;يا يې په سوک ووهى، نو هغه د قتل مجرم دے او هغه به وژلے شى. د مړى د نزدې خپلوانو دا ذمه وارى ده چې قاتِل مړ کړى. هغوئ يې چې کله هم پېدا کړى، نو وبه يې وژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4448, 'Numbers 35:22', 'Numbers', 35, 22, '&nbsp;خو کۀ يو کس په غلطۍ سره څوک ووژنى چې د هغۀ سره يې کينه نۀ وى، کۀ په څۀ يې وولى او يا ديکه ورکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4449, 'Numbers 35:23', 'Numbers', 35, 23, '&nbsp;يا چې د چا خيال نۀ وى او يو کاڼے وولى او څوک ورباندې مړ شى اګر چې هغۀ له يې د تکليف رسولو اراده نۀ وى او دشمن يې هم نۀ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4450, 'Numbers 35:24', 'Numbers', 35, 24, '&nbsp;نو په داسې حالاتو کښې به جرګه د هغه کس په حق کښې فېصله کوى د چا نه چې مړے شوے وى، نۀ چې د هغه مړ کس د خپلوان په حق کښې چې بدل اخستل غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4451, 'Numbers 35:25', 'Numbers', 35, 25, '&nbsp;جرګه به د مړى د خپلوان نه هغه کس بچ کوى چې په غلطۍ سره د قتل مجرم وى او هغوئ به هغه واپس د پناه ښار ته بوځى کوم ته چې تښتېدلے وى. هغه به هلته تر هغې پورې ايساريږى چې مشر اِمام مړ نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4452, 'Numbers 35:26', 'Numbers', 35, 26, '&nbsp;چې کوم کس په غلطۍ سره د قتل مجرم وى کۀ هغه د پناه د ښار نه لاړ شى کوم له چې ورتښتېدلے وى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4453, 'Numbers 35:27', 'Numbers', 35, 27, '&nbsp;او د مړى خپلوان هغه پېدا کړى او وې وژنى، نو د دې بدل اخستلو په وجه هغه ګناهګار نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4454, 'Numbers 35:28', 'Numbers', 35, 28, '&nbsp;کوم کس چې په غلطۍ سره د قتل کولو مجرم وى هغه به خامخا د پناه په ښار کښې تر هغه وخته پورې پاتې کيږى چې تر کومې پورې مشر اِمام مړ نۀ وى، خو د هغې نه پس هغه واپس کور ته تلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4455, 'Numbers 35:29', 'Numbers', 35, 29, '&nbsp;دا قانون به ستاسو او ستاسو د اولاد دپاره وى چې په هر ځائ کښې اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4456, 'Numbers 35:30', 'Numbers', 35, 30, '&nbsp;چې په چا باندې د قتل اِلزام وى نو هغه به صِرف په هغه وخت مجرم ګڼلے شى او مړ کولے به شى چې په هغۀ باندې دوه کسان يا دوو نه زيات ګواهان ګواهى ورکړى، د يو کس ګواهى د قتل د اِلزام ثابِتولو دپاره کافى نۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4457, 'Numbers 35:31', 'Numbers', 35, 31, '&nbsp;قاتِل به خامخا وژلے شى. هغه د دې سزا نه په دې نۀ شى خلاصېدلے چې د صُلحې پېسې ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4458, 'Numbers 35:32', 'Numbers', 35, 32, '&nbsp;کۀ څوک د پناه ښار ته تښتېدلے وى، نو هغه دې ته مۀ پرېږدئ چې د مشر اِمام د مرګ نه مخکښې د صُلحې پېسې ورکړى د دې دپاره چې کور ته واپس راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4459, 'Numbers 35:33', 'Numbers', 35, 33, '&nbsp;هغه مُلک مۀ پليتوئ چې چرته تاسو اوسېږئ، ځکه د وينې تويَول د هغه مُلک پليتول دى او چې په کومه زمکه باندې وينه توئ شى نو د هغې کفاره نۀ شى ادا کېدلے، زمکه د هغه کس د وينې تويَولو نه بغېر نۀ پاکيږى چا چې وينه توئ کړې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4460, 'Numbers 35:34', 'Numbers', 35, 34, '&nbsp;هغه مُلک مۀ پليتوئ چرته چې تاسو اوسېږئ، ځکه چې زۀ مالِک خُدائ يم او د بنى اِسرائيلو په مينځ کښې اوسېږم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4461, 'Numbers 36:1', 'Numbers', 36, 1, '&nbsp;د جِلعاد د قبيلې د کورَنو مشران، د مکير زوئ او د منسى نمسے چې د يوسف زوئ وو، موسىٰ او د بنى اِسرائيلو نورو مشرانو له لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4462, 'Numbers 36:2', 'Numbers', 36, 2, '&nbsp;هغوئ ووئيل، ”صاحِبه، مالِک خُدائ تا ته حُکم درکړے دے چې زمکه د پچې په ذريعه په بنى اِسرائيلو تقسيم کړه. مالِک خُدائ دا حُکم هم کړے دے چې زمونږ د خپلوان صِلافحاد جائيداد د هغۀ لوڼو له ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4463, 'Numbers 36:3', 'Numbers', 36, 3, '&nbsp;خو دا خبره ياده ساته. کۀ هغوئ د بلې قبيلې سړو سره ودونه وکړل، نو د هغوئ جائيداد به د هغه قبيلې شى او زمونږ برخه به کمه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4464, 'Numbers 36:4', 'Numbers', 36, 4, '&nbsp;د واپس ورکولو په کال کښې، کله چې کوم جائيداد خرڅ شوے وى او هغه واپس خپل اصلى مالِک ته ملاويږى، نو د صِلافحاد د لوڼو جائيداد به د همېشه دپاره هغه قبېلې ته ورکړے شى چې په کومه کښې وادۀ شوې وى او دا به زمونږ د قبيلې دپاره د تاوان خبره وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4465, 'Numbers 36:5', 'Numbers', 36, 5, '&nbsp;نو موسىٰ بنى اِسرائيلو ته د مالِک خُدائ دا حُکمونه واورول. هغۀ وفرمائيل، ”د منسى قبيله چې څۀ وائى هغه ټيک دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4466, 'Numbers 36:6', 'Numbers', 36, 6, '&nbsp;او مالِک خُدائ فرمائى چې د صِلافحاد لوڼه آزادې دى چې د چا سره هم وادۀ کول غواړى خو په خپله قبيله کښې به يې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4467, 'Numbers 36:7', 'Numbers', 36, 7, '&nbsp;د يوې بنى اِسرائيلۍ قبيلې جائيداد به بلې قبيلې ته نۀ شى ورکولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4468, 'Numbers 36:8', 'Numbers', 36, 8, '&nbsp;هره يوه ښځه چې په کومه بنى اِسرائيلى قبيله کښې ميراث اخلى نو هم د هغه قبيلې د سړى سره به وادۀ کوى. نو داسې ټولو بنى اِسرائيلو ته به د خپل پلار نيکۀ په جائيداد کښې ميراث ملاويږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4469, 'Numbers 36:9', 'Numbers', 36, 9, '&nbsp;او د يوې قبيلې جائيداد به بلې قبيلې ته نۀ ملاويږى. هره بنى اِسرائيلى قبيله به خامخا خپله د ميراث زمکه لرى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4470, 'Numbers 36:12', 'Numbers', 36, 12, '&nbsp;هغوئ د يوسف زوئ منسى قبيلې په کورَنو کښې ودونه وکړل او د هغوئ جائيداد د هغوئ د پلار په قبيله کښې پاتې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4471, 'Numbers 36:13', 'Numbers', 36, 13, '&nbsp;دا هغه اصُول او قانون دے کوم چې مالِک خُدائ د موسىٰ په ذريعه د موآب په مېدانونو کښې د اُردن نه پورې يريحو ته مخامخ بنى اِسرائيلو له ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4472, 'Deuteronomy 1:1', 'Deuteronomy', 1, 1, '&nbsp;په دې کِتاب کښې هغه خبرې دى کومې چې موسىٰ ټولو بنى اِسرائيلو ته وکړې کله چې هغوئ د اُردن سيند نمرخاتۀ طرف ته په صحرا کښې وُو. هغوئ سوف ته نزدې د اُردن په مېدان کښې وُو، دا د هغې ښارونو په مينځ کښې دے چې د فاران ښار يې يو طرف ته دے او د طوفل، لابن، حصيروت، او د ديذهب ښارونه يې په بل طرف دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4473, 'Deuteronomy 1:2', 'Deuteronomy', 1, 2, '&nbsp;د غرونو مُلک ادوم په لاره د سينا غرۀ نه واخله تر قادِس برنيع پورې د يوولسو ورځو مزل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4474, 'Deuteronomy 1:3', 'Deuteronomy', 1, 3, '&nbsp;د هغوئ د مِصر نه د راوتلو نه څلوېښت کاله پس د يوولسمې مياشتې په وړومبۍ ورځ، موسىٰ بنى اِسرائيلو ته هغه هر څۀ وفرمائيل چې مالِک خُدائ هغۀ ته د وئيلو حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4475, 'Deuteronomy 1:4', 'Deuteronomy', 1, 4, '&nbsp;دا د هغې نه وروستو وُو چې مالِک خُدائ د اموريانو بادشاه سيحون له شکست ورکړے وو، چې هغۀ د حسبون په ښار بادشاهى کوله او د بسن بادشاه عوج، چې هغۀ د عستارات او ادرعى په ښارونو بادشاهى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4476, 'Deuteronomy 1:5', 'Deuteronomy', 1, 5, '&nbsp;دا هغه وخت وو کله چې اِسرائيليان د اُردن نمرخاتۀ طرف ته د موآب په علاقه کښې وُو چې د خُدائ پاک په قانون او حُکمونو باندې موسىٰ هغوئ پوهول شروع کړل. هغۀ وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4477, 'Deuteronomy 1:6', 'Deuteronomy', 1, 6, '&nbsp;”کله چې مونږ د سينا غرۀ سره وُو نو مالِک خُدائ زمونږ خُدائ پاک مونږ ته وفرمائيل چې تاسو د دې غرۀ سره ډېر زيات ايسار شوى يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4478, 'Deuteronomy 1:7', 'Deuteronomy', 1, 7, '&nbsp;خېمې اوچتې کړئ او په سفر روان شئ. د اموريانو د غرونو مُلک او ټولو ګېرچاپېره علاقو ته لاړ شئ چې د اُردن مېدان، د غرونو مُلک او لاندې علاقې، د صحرا علاقه او د مديترانى د سمندر غاړه په کښې ده. د کنعان مُلک ته او د لبنان غرونو نه اخوا د فرات لوئ سيند پورې لاړ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4479, 'Deuteronomy 1:8', 'Deuteronomy', 1, 8, '&nbsp;ګورئ، دا هغه ټوله زمکه ده د کومې چې ما، مالِک خُدائ، ستاسو پلار نيکۀ، اِبراهيم، اِسحاق، يعقوب او د هغوئ د اولاد سره د ورکولو وعده کړې ده. لاړ شئ او هغه قبضه کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4480, 'Deuteronomy 1:9', 'Deuteronomy', 1, 9, '&nbsp;موسىٰ خلقو ته وفرمائيل، ”کوم وخت چې مونږ لا د سينا غرۀ سره وُو، نو ما تاسو ته وفرمائيل چې زۀ په يواځې ځان ستاسو ذمه وارى نۀ شم اخستے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4481, 'Deuteronomy 1:10', 'Deuteronomy', 1, 10, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک تاسو د آسمان د ستورو په شان بې‌شمېره کړى يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4482, 'Deuteronomy 1:11', 'Deuteronomy', 1, 11, '&nbsp;مالِک خُدائ، ستاسو د پلار نيکۀ خُدائ پاک دې تاسو يو په زر زيات کړى او هغه دې تاسو دولتمند کړى، لکه څنګه چې هغۀ وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4483, 'Deuteronomy 1:12', 'Deuteronomy', 1, 12, '&nbsp;خو زۀ يواځې د لانجو فېصله کولو دا دومره لويه ذمه وارى څنګه برداشت کړم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4484, 'Deuteronomy 1:13', 'Deuteronomy', 1, 13, '&nbsp;د هرې قبيلې نه يو څو هوښيار، پوهه لرونکى او تجربه‌کار سړى خوښ کړئ او زۀ به هغوئ په تاسو مشران جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4485, 'Deuteronomy 1:14', 'Deuteronomy', 1, 14, '&nbsp;او تاسو زما سره متفِق شوئ او ومو وئيل چې دا به ډېر ښۀ کار وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4486, 'Deuteronomy 1:15', 'Deuteronomy', 1, 15, '&nbsp;نو ما هغه هوښيار او تجربه‌کاره مشران واخستل چې تاسو د خپلو قبيلو نه خوښ کړى وُو او هغوئ مې ستاسو مشران جوړ کړل. چې څۀ د زرو، څۀ د سلو، څۀ د پنځوسو، او څۀ د لسو کسانو ذمه وار وُو. ما ستاسو د قبيلو دپاره نور مشران هم مقرر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4487, 'Deuteronomy 1:16', 'Deuteronomy', 1, 16, '&nbsp;په هغه وخت ما ستاسو قاضيانو له حُکم ورکړو چې ستاسو د خلقو په مينځ کښې کومې لانجې راځى نو هغې ته غوږ نيسئ. هره يوه لانجه په اِنصاف سره فېصله کوئ، کۀ د دې لانجې تعلق صِرف ستاسو خپلو خلقو سره وى يا کۀ په کښې هغه مسافر هم شريک وى کوم چې ستاسو سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4488, 'Deuteronomy 1:17', 'Deuteronomy', 1, 17, '&nbsp;په فېصلو کښې د چا طرفدارى مۀ کوئ، د هر چا سره يو شان اِنصاف کوئ، دې خبرې ته مۀ ګورئ چې هغه مالدار دے او کۀ غريب. د هيچا نه مۀ يرېږئ، ځکه چې کومې فېصلې تاسو کوئ هغه د خُدائ پاک د طرف نه وى. کۀ يوه لانجه ستاسو دپاره ډېره مشکله وى نو ما له يې راوړئ چې زۀ يې هواره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4489, 'Deuteronomy 1:18', 'Deuteronomy', 1, 18, '&nbsp;هم په هغه وخت ما د هغه نورو ټولو څيزونو حُکم درکړو چې تاسو يې کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4490, 'Deuteronomy 1:19', 'Deuteronomy', 1, 19, '&nbsp;مونږ هم هغه شان وکړل چې څنګه مالِک خُدائ زمونږ خُدائ پاک حُکم راکړے وو. مونږ د سينا غرۀ نه لاړُو او په هغه لوئ او خطرناک بيابان کښې د اموريانو غرونو مُلک پورې روان وُو. کله چې مونږ قادِس برنيع ته ورسېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4491, 'Deuteronomy 1:22', 'Deuteronomy', 1, 22, '&nbsp;خو تاسو ما له راغلئ او ومو وئيل چې د ځان نه مخکښې به سړى ولېږُو چې هغه مُلک وګورى او مونږ ته ووائى چې د ورتلو دپاره کومه لار ښۀ ده او هلته ښارونه څنګه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4492, 'Deuteronomy 1:23', 'Deuteronomy', 1, 23, '&nbsp;دا خبره په ما ښۀ ولګېده، نو ما د دولسو قبيلو نه يو يو سړے خوښ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4493, 'Deuteronomy 1:24', 'Deuteronomy', 1, 24, '&nbsp;هغوئ د اسکال وادى پورې د غرونو مُلک ته د معلوماتو حاصلولو دپاره لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4494, 'Deuteronomy 1:25', 'Deuteronomy', 1, 25, '&nbsp;هغوئ چې هلته کومه مېوه وموندله نو لږه يې ترې نه راوړه او هغوئ وفرمائيل چې مالِک خُدائ زمونږ خُدائ پاک چې کوم مُلک مونږ له راکوى هغه ډېر آباد دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4495, 'Deuteronomy 1:26', 'Deuteronomy', 1, 26, '&nbsp;خو تاسو د مالِک خُدائ زمونږ د خُدائ پاک د حُکم نه سرکشى وکړه او هغه مُلک ته وردننه نۀ شوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4496, 'Deuteronomy 1:27', 'Deuteronomy', 1, 27, '&nbsp;تاسو يو بل ته وغورېدئ او ومو وئيل، مالِک خُدائ زمونږ نه نفرت کوى. هغۀ مونږ د مِصر مُلک نه صِرف د دې دپاره راوويستلو چې اموريانو ته مو حواله کړى چې هغوئ مونږ ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4497, 'Deuteronomy 1:28', 'Deuteronomy', 1, 28, '&nbsp;مونږ هلته ولې لاړ شُو؟ مونږ يريږو. کوم سړى چې مونږ هلته لېږلى وُو هغوئ مونږ ته ووئيل چې د هغه ځائ خلق زمونږ نه تکړه او لوړ لوړ دى او هغوئ په داسې ښارونو کښې اوسيږى چې دېوالونه يې آسمان ته رسيږى. هغوئ هلته دېوان هم وليدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4498, 'Deuteronomy 1:29', 'Deuteronomy', 1, 29, '&nbsp;خو ما درته ووئيل چې د هغه خلقو نه مۀ يرېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4499, 'Deuteronomy 1:30', 'Deuteronomy', 1, 30, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک به ستاسو لارښودنه وکړى او هغه به ستاسو دپاره جنګ کوى، هم هغه شان لکه څنګه چې هغۀ ستاسو په مخکښې په مِصر کښې وکړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4500, 'Deuteronomy 1:31', 'Deuteronomy', 1, 31, '&nbsp;او په بيابان کښې يې چې څۀ وکړل. نو تاسو په خپلو سترګو وليدل چې هغۀ تاسو په حِفاظت سره تر دې ځائ پورې داسې راوستلئ، لکه چې پلار خپل زوئ بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');